// Mede o carregamento a partir do menu para diagnóstico.

#if DEVELOPMENT_BUILD || UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using SchoolMenu;
namespace HorrorGame{
 // Included only in development players; refuses the real game's product/save namespace.
 public sealed class LoadingBenchmark:MonoBehaviour{
  string output;bool failed,drawn;Camera measuredCamera;RenderTexture measuredTarget;readonly List<RenderTexture> textures=new List<RenderTexture>();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){var args=Environment.GetCommandLineArgs();int n=Array.IndexOf(args,"--wotp-loading-output");if(n<0||n+1>=args.Length||!Debug.isDebugBuild||!Application.productName.EndsWith("Loading Benchmark",StringComparison.Ordinal))return;var go=new GameObject("Disposable loading benchmark");DontDestroyOnLoad(go);var b=go.AddComponent<LoadingBenchmark>();b.output=Path.GetFullPath(args[n+1]);Directory.CreateDirectory(b.output);Application.runInBackground=true;PlayerPrefs.SetInt("HorrorMenu.Calibrated",1);foreach(string key in new[]{"BeforeDemolition.ResumeRequested","BeforeDemolition.StoryCarryRequested","Game.ResumeRequested","Game.StoryCarryRequested"})PlayerPrefs.SetInt(key,0);SceneManager.sceneLoaded+=b.Loaded;Application.logMessageReceived+=b.Error;}
  void Loaded(Scene scene,LoadSceneMode mode){foreach(var old in textures){old.Release();Destroy(old);}textures.Clear();var game=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<GameSession>(true)).FirstOrDefault();measuredCamera=game&&game.player&&game.player.view?game.player.view.playerCamera:scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>(true)).FirstOrDefault(c=>c.CompareTag("MainCamera"));drawn=false;if(measuredCamera){measuredTarget=new RenderTexture(1280,720,24,RenderTextureFormat.DefaultHDR);measuredTarget.Create();measuredCamera.targetTexture=measuredTarget;measuredCamera.enabled=true;textures.Add(measuredTarget);}if(game&&game.input&&game.input.Actions)game.input.Actions.devices=Array.Empty<UnityEngine.InputSystem.InputDevice>();}
  void LateUpdate(){if(drawn||!measuredCamera||!measuredTarget)return;var game=GameSession.Instance;if(game&&(game.IsRestoringCheckpoint||!game.narrative||!game.narrative.IsInitialized))return;RenderPipeline.SubmitRenderRequest(measuredCamera,new RenderPipeline.StandardRequest{destination=measuredTarget,isPreview=false});drawn=true;}
  void Error(string message,string stack,LogType type){if(type!=LogType.Exception&&type!=LogType.Error&&type!=LogType.Assert)return;failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),message+"\n"+stack);LoadingMetrics.Flush();Application.Quit(3);}
  IEnumerator Until(Func<bool> condition,string label,double seconds=150){double end=LoadingMetrics.Now+seconds;while(!condition()&&LoadingMetrics.Now<end&&!failed)yield return null;if(!condition()&&!failed){failed=true;File.WriteAllText(Path.Combine(output,"failure.txt"),"Timeout: "+label);LoadingMetrics.Flush();Application.Quit(4);}}
  static bool Ready(string scene)=>GameSession.Instance&&GameSession.Instance.gameObject.scene.name==scene&&GameSession.Instance.narrative.IsInitialized&&GameSession.Instance.CanControl;
  IEnumerator Menu(){yield return Until(()=>SceneManager.GetActiveScene().name=="MainMenu"&&FindAnyObjectByType<MainMenuController>(),"menu scene");var m=FindAnyObjectByType<MainMenuController>();yield return Until(()=>!m.fader||m.fader.curtain.alpha<=0,"menu fade");yield return Until(()=>!(bool)typeof(MainMenuController).GetField("busy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(m),"menu idle");yield return null;}
  IEnumerator Return(string label){LoadingMetrics.Label=label;GameSession.Instance.ReturnToMenu();yield return Menu();yield return Until(()=>LoadingMetrics.Current!=null&&LoadingMetrics.Current.playable>=0,"menu measurement");}
  IEnumerator Continue(string scene,int iteration){var game=GameSession.Instance;if(!game.save.Save()){Error("Benchmark checkpoint could not be saved",scene,LogType.Error);yield break;}yield return Return("return-"+scene+"-"+iteration);LoadingMetrics.Label="continue-"+scene+"-"+iteration;FindAnyObjectByType<MainMenuController>().BeginGame(true);yield return Until(()=>Ready(scene),"continue "+scene);yield return Until(()=>LoadingMetrics.Current!=null&&LoadingMetrics.Current.playable>=0,"continue first frame");}
  [Serializable]class OfficeState{public EmailInboxState emails;}
  SaveData ExitSeed(GameSession g,bool road){var inbox=road?g.GetComponent<BeforeDemolitionRoadFlow>().inbox:g.GetComponent<BeforeDemolitionOfficeFlow>().inbox;var cat=inbox.catalog;var emails=EmailInboxState.Create(cat);foreach(string id in new[]{"email.01","email.06","email.07"})emails.MarkRead(cat,id);if(road)emails.Deliver(cat,"email.08");var progress=new NarrativeProgress{storyId=BeforeDemolitionCampaign.StoryId,storyRevision=BeforeDemolitionCampaign.Revision,chapterId=road?BeforeDemolitionCampaign.RoadChapterId:BeforeDemolitionCampaign.OfficeChapterId,pendingChapterId=road?BeforeDemolitionCampaign.SchoolChapterId:BeforeDemolitionCampaign.RoadChapterId,milestones=new List<string>{BeforeDemolitionCampaign.ReadySignal,BeforeDemolitionCampaign.ExitSignal},completedChapters=new List<string>{BeforeDemolitionCampaign.OfficeChapterId}};if(road){progress.milestones.AddRange(BeforeDemolitionCampaign.RoadSignals);progress.completedChapters.Add(BeforeDemolitionCampaign.RoadChapterId);}var data=new SaveData{scene=g.gameObject.scene.name,position=g.player.transform.position,heading=g.player.transform.eulerAngles.y,battery=240,stamina=100,narrative=progress,inventory=new List<InventoryItem>{new InventoryItem{id=BeforeDemolitionCampaign.WhistleItemId,note=true,inspectionId=BeforeDemolitionCampaign.WhistleItemId}}};foreach(string id in emails.readIds)data.inventory.Add(new InventoryItem{id="bd.note."+id,note=true});if(road){data.inventory.Add(new InventoryItem{id=BeforeDemolitionRoadFlow.EmailDeliveryItemId});data.objects.Add(new SavedObject{id=BeforeDemolitionRoadFlow.StateId,json=JsonUtility.ToJson(new BeforeDemolitionRoadState{phase=RoadRadioPhase.Parked,emails=emails})});}else data.objects.Add(new SavedObject{id=BeforeDemolitionCampaign.FlowStateId,json=JsonUtility.ToJson(new OfficeState{emails=emails})});return data;}
  IEnumerator Carry(bool road,int iteration){var g=GameSession.Instance;g.ShowStoryScreen();if(!g.save.RestoreSnapshot(ExitSeed(g,road))){Error("Benchmark source seed rejected",g.gameObject.scene.name,LogType.Error);yield break;}if(!road)g.GetComponent<BeforeDemolitionOfficeFlow>().RestoreWorldSilently();yield return new WaitForSecondsRealtime(road?20:8);LoadingMetrics.Label=(road?"road-school-":"office-road-")+iteration;string target=road?"SchoolCEEP":"RoadJourney";if(!g.LoadStoryChapter(target)){Error("Chapter handoff rejected",target,LogType.Error);yield break;}yield return Until(()=>Ready(target),"carry "+target);yield return Until(()=>LoadingMetrics.Current!=null&&LoadingMetrics.Current.playable>=0,"carry rendered frame");if(!GameSession.Instance.interaction.inventory.Contains(BeforeDemolitionCampaign.WhistleItemId))Error("Whistle lost across handoff",target,LogType.Error);}
  IEnumerator Start(){if(string.IsNullOrEmpty(output))yield break;yield return Menu();for(int i=0;i<3&&!failed;i++){
   LoadingMetrics.Label="new-office-"+i;var menu=FindAnyObjectByType<MainMenuController>();menu.BeginGame(false);yield return Until(()=>menu&&menu.chapterSelection&&menu.chapterSelection.chapterGroup.interactable,"chapter selection");yield return Until(()=>!(bool)typeof(MainMenuController).GetField("busy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(menu),"chapter selection idle");menu.StartChapter();yield return Until(()=>Ready("Chapter1Office"),"new office");yield return Until(()=>LoadingMetrics.Current!=null&&LoadingMetrics.Current.playable>=0,"new office rendered");yield return Continue("Chapter1Office",i);yield return Carry(false,i);yield return Continue("RoadJourney",i);yield return Carry(true,i);yield return Continue("SchoolCEEP",i);yield return Return("final-return-"+i);
  }if(!failed){LoadingMetrics.Flush();File.WriteAllText(Path.Combine(output,"complete.json"),JsonUtility.ToJson(new Completed{passed=true,transitions=LoadingMetrics.Data.samples.Count,product=Application.productName,persistentDataPath=Application.persistentDataPath},true));Application.Quit(0);}}
  [Serializable]class Completed{public bool passed;public int transitions;public string product,persistentDataPath;}
 }
}
#endif
